CREATE TRIGGER trial_attempts_no_delete BEFORE DELETE ON trial_attempts BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER delegation_no_update BEFORE UPDATE ON owner_conditional_delegations BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER delegation_no_delete BEFORE DELETE ON owner_conditional_delegations BEGIN SELECT RAISE(ABORT,'append-only'); END;
